<?php
require_once __DIR__.'/lib.php';require_admin();$user=current_user();$posts=load_json('posts.json',[]);$users=load_json('users.json',[]);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=$_POST['action']??'';
 try{
 if($action==='post'){$title=trim($_POST['title']??'');$body=trim($_POST['body']??'');if($title===''||$body==='')throw new RuntimeException('Add both a title and the update text.');if(mb_strlen($title)>140)throw new RuntimeException('Title must be 140 characters or fewer.');$img=upload_image();array_unshift($posts,['id'=>bin2hex(random_bytes(8)),'title'=>$title,'body'=>$body,'image'=>$img,'author'=>$user['name'],'created'=>date('c')]);save_json('posts.json',$posts);flash('Your update has been published.');redirect('dashboard.php');}
 if($action==='delete_post'){$id=$_POST['id']??'';$posts=array_values(array_filter($posts,fn($p)=>($p['id']??'')!==$id));save_json('posts.json',$posts);flash('Post deleted.');redirect('dashboard.php');}
 if($action==='add_admin'){if(($user['role']??'')!=='owner')throw new RuntimeException('Only the first administrator (owner) can add administrators.');if(count($users)>=3)throw new RuntimeException('The platform supports up to three administrator accounts.');$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10)throw new RuntimeException('Enter a name, valid email and password of at least 10 characters.');foreach($users as $u)if(strtolower($u['email'])===$email)throw new RuntimeException('That email already has an administrator account.');$users[]=['id'=>bin2hex(random_bytes(8)),'name'=>$name,'email'=>$email,'hash'=>password_hash($pass,PASSWORD_DEFAULT),'role'=>'admin'];save_json('users.json',$users);flash('Administrator account created. Share the login details privately.');redirect('dashboard.php');}
 }catch(Throwable $e){$error=$e->getMessage();}
}
$comments=load_json('comments.json',[]);$flash=flash();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dashboard | AISON PROMOTIONZ</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">AP</span><span>AISON <b>PROMOTIONZ</b><small>ADMIN DASHBOARD</small></span></a><nav class="nav"><a href="index.php">View website ↗</a><a href="discussion.php">Discussions</a><a class="nav-admin" href="logout.php">Log out</a></nav></header><main class="dashboard"><div class="dashboard-head"><div><p class="eyebrow">CONTROL CENTRE</p><h1>Welcome, <?=h($user['name'])?></h1><p class="muted">Publish news, promote events and stay connected with customers.</p></div><span class="role-pill"><?=h(strtoupper($user['role']))?></span></div><?php if($flash):?><div class="success"><?=h($flash)?></div><?php endif;?><?php if($error):?><div class="alert"><?=h($error)?></div><?php endif;?>
<div class="dashboard-grid"><section class="panel"><p class="eyebrow">CONTENT MANAGER</p><h2>Publish an update</h2><p class="muted">Your post appears on the public home page immediately after publishing.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="post"><label>Post title<input name="title" maxlength="140" required placeholder="e.g. Upcoming live music event"></label><label>What would you like to share?<textarea name="body" rows="7" required placeholder="Write your announcement, event details, artist news or promotion…"></textarea></label><label>Attach a photo or poster (optional)<input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif"><small>Maximum 5 MB. JPG, PNG, WEBP or GIF.</small></label><button class="btn btn-orange" type="submit">Publish update ↗</button></form></section>
<section class="panel"><p class="eyebrow">YOUR PLATFORM</p><h2>Quick overview</h2><div class="stats"><div><strong><?=count($posts)?></strong><span>Published posts</span></div><div><strong><?=count($comments)?></strong><span>Discussion messages</span></div><div><strong><?=count($users)?>/3</strong><span>Admin accounts</span></div></div><a class="btn btn-dark btn-full" href="discussion.php">Open customer discussions →</a><div class="divider"></div><h3>Administrator accounts</h3><ul class="admin-list"><?php foreach($users as $u):?><li><span class="avatar"><?=h(strtoupper(substr($u['name'],0,1)))?></span><span><strong><?=h($u['name'])?></strong><small><?=h($u['email'])?></small></span><em><?=h($u['role'])?></em></li><?php endforeach;?></ul><?php if(($user['role']??'')==='owner'&&count($users)<3):?><details class="add-admin"><summary>+ Add another administrator</summary><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="add_admin"><label>Full name<input name="name" required maxlength="80"></label><label>Email<input type="email" name="email" required></label><label>Temporary password<input type="password" name="password" required minlength="10"><small>At least 10 characters; share privately.</small></label><button class="btn btn-orange" type="submit">Create admin</button></form></details><?php endif;?></section></div>
<section class="panel post-management"><div class="split-heading"><div><p class="eyebrow">PUBLISHED CONTENT</p><h2>Manage posts</h2></div><span class="role-pill"><?=count($posts)?> total</span></div><?php if(!$posts):?><p class="muted">No posts yet. Publish your first update above.</p><?php else:?><div class="manage-list"><?php foreach($posts as $p):?><div class="manage-item"><div><?php if(!empty($p['image'])):?><img src="<?=h($p['image'])?>" alt=""><?php endif;?><span><strong><?=h($p['title'])?></strong><small><?=h(date('M j, Y',strtotime($p['created']??'now')))?> · <?=h($p['author']??'')?></small></span></div><form method="post" onsubmit="return confirm('Delete this post?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete_post"><input type="hidden" name="id" value="<?=h($p['id']??'')?>"><button class="btn btn-danger" type="submit">Delete</button></form></div><?php endforeach;?></div><?php endif;?></section></main><footer class="auth-footer">Keep your password private. Log out when using a shared device.</footer></body></html>
